output_text:
[
  {
    "id": "must_take_cart",
    "text": "Shoppers are obliged to obtain a shopping cart at some point during the trip.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    }
  },
  {
    "id": "exit_with_cart",
    "text": "Shoppers are prohibited from leaving the store unless they have a shopping cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_item_cell",
    "text": "Shoppers are prohibited from being at the item location at column 3 row 1 while holding a cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(3,1)",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "no_cart_in_north_aisle",
    "text": "Shoppers are prohibited from taking a cart into the narrow aisle consisting of cells at column 3 rows 1 and 2.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          {
            "or": [
              "at(3,1)",
              "at(3,2)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "park_cart_before_aisle",
    "text": "Shoppers who reach the cart-parking cell at column 3 row 3 with a cart are obliged to interact there before entering the aisle.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,3)",
          "hasCart"
        ]
      },
      "discharge": {
        "and": [
          "at(3,3)",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_item",
    "text": "After interacting at the item location at column 3 row 1, shoppers are obliged to return to column 3 row 3 and interact there.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,1)",
          "INTERACT"
        ]
      },
      "discharge": {
        "and": [
          "at(3,3)",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "cart_required_on_south_exit_route",
    "text": "Shoppers are prohibited from traveling along the bottom exit route without a cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "not": "hasCart"
          },
          {
            "or": [
              "at(3,7)",
              "at(4,7)",
              "at(5,7)",
              "at(6,7)",
              "at(7,7)",
              "at(8,7)",
              "at(9,7)",
              "at(10,7)",
              "at(11,7)"
            ]
          }
        ]
      }
    }
  },
  {
    "id": "no_exit_before_cart_return",
    "text": "Once a shopper has interacted at column 3 row 1, they are obliged to have a cart again before exiting.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": {
        "and": [
          "at(3,1)",
          "INTERACT"
        ]
      },
      "discharge": "hasCart"
    }
  }
]
